"""Password hashing for local accounts."""

import hashlib
import hmac
import secrets

_ITERATIONS = 600_000


def _derive(password: str, salt: bytes) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, _ITERATIONS)


def hash_password(password: str) -> str:
    """Return a salted hash suitable for storing in the users table."""
    salt = secrets.token_bytes(16)
    return f"{salt.hex()}${_derive(password, salt).hex()}"


def verify_password(password: str, stored: str) -> bool:
    """Check a candidate password against a stored hash."""
    salt_hex, digest_hex = stored.split("$", 1)
    candidate = _derive(password, bytes.fromhex(salt_hex))
    return hmac.compare_digest(candidate, bytes.fromhex(digest_hex))

