export function evaluateFormula(formula: string, row: Row): number {
  const tokens = tokenize(formula);
  let pos = 0;

  const primary = (): number => {
    const token = tokens[pos++];
    if (token === undefined) throw new Error("Unexpected end of formula");
    if (token === "(") {
      const value = sum();
      if (tokens[pos++] !== ")") throw new Error("Expected )");
      return value;
